<?php defined( 'ABSPATH' ) || exit; get_header(); while ( have_posts() ) : the_post(); ?>
<article class="container prose section-pad"><?php $canarw_cat = canarw_post_category_label( get_the_ID() ); ?><span class="eyebrow"><?php echo esc_html( trim( $canarw_cat . ( $canarw_cat ? ' · ' : '' ) . get_the_date() ) ); ?></span><h1><?php the_title(); ?></h1><?php $canarw_image = canarw_post_image( get_the_ID() ); if ( $canarw_image && ! post_password_required() ) { echo '<img class="blog-hero" src="' . esc_url( $canarw_image ) . '" alt="' . esc_attr( get_the_title() ) . '">'; } ?><?php the_content(); wp_link_pages(); the_tags( '<p>', ', ', '</p>' ); ?><p><a class="text-link" href="<?php echo esc_url( canarw_permalink_for_source( canarw_is_english() ? '/en/blog' : '/blog' ) ); ?>"><?php echo esc_html( canarw_label( 'العودة إلى المدونة', 'Back to the blog' ) ); ?></a></p></article>
<?php if ( comments_open() || get_comments_number() ) { comments_template(); } endwhile; get_footer(); ?>
